// barWidth: a bar's length as a share of the longest (0–100, at least 1 so
// every bar shows).
func barWidth(n, max int) templ.SafeCSS {
	w := 100.0
	if max > 0 {
		w = float64(n) * 100 / float64(max)
	}
	if w < 1 {
		w = 1
	}
	return templ.SafeCSS(fmt.Sprintf("--w: %.1f", w))
}

